                insights.push(window.mySimulation.t('insight_overvalued'));
            }

            var overallScore = Math.max(0, Math.min(100, Math.round(avgScore)));
            return {
                totalScore: totalScore,
                avgScore: Math.round(avgScore),
                overallScore: overallScore,
                score: overallScore,
                maxPossible: maxPossible,
                enterpriseValue: lastEV,
                sharePrice: lastSP,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.roundScore >= 90) return window.mySimulation.t('hint_excellent');
            if (results.roundScore >= 70) return window.mySimulation.t('hint_good');
            if (results.roundScore >= 50) return window.mySimulation.t('hint_moderate');
